-- Preferences are per account; changing them never changes access permissions.
CREATE TABLE user_notification_preferences(user_id TEXT PRIMARY KEY REFERENCES users(id), case_updates INTEGER NOT NULL DEFAULT 1 CHECK(case_updates IN (0,1)), updated_at TEXT NOT NULL);
-- Change only known fixture labels in explicitly registered demonstration houses. No cases or identities are deleted.
